:root {
  --brand-primary: #003381;
  --brand-primary-hover: #002966;
  --brand-primary-soft: rgba(0, 51, 129, 0.08);
  --brand-primary-border: rgba(0, 51, 129, 0.2);
  --surface: #ffffff;
  --surface-subtle: #f7f8fa;
  --border: #dde2e9;
  --text: #20242a;
  --text-muted: #626b78;
}
html,
body,
#container {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0;
  overflow: hidden;
  background: var(--surface-subtle);
}
.fc-root-provider {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
*,
*::before,
*::after {
  box-sizing: border-box;
}
button,
input,
select,
textarea {
  font: inherit;
}
:where(button, input, select, textarea, summary, [tabindex]):focus-visible {
  outline: 2px solid var(--brand-primary);
  outline-offset: 2px;
}
.fc-app {
  display: flex;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  flex-direction: column;
  background: var(--surface-subtle);
  color: var(--text);
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, sans-serif;
}
.fc-shell {
  flex: 1 1 auto;
  width: 100%;
  max-width: 720px;
  min-width: 0;
  min-height: 0;
  margin: 0 auto;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 14px clamp(12px, 4vw, 24px) 32px;
  overscroll-behavior: contain;
}
.fc-shell--settings {
  background: white;
}
.fc-header {
  position: relative;
  z-index: 30;
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 14px;
}
.fc-brand {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 9px;
}
.fc-brand img,
.fc-empty-state img {
  flex: 0 0 auto;
  object-fit: contain;
}
.fc-brand h1 {
  margin: 0;
  color: var(--brand-primary);
  font-size: 18px;
  font-weight: 700;
  line-height: 1.15;
}
.fc-brand p {
  margin: 2px 0 0;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.2;
}
.fc-modes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 3px;
  margin-bottom: 12px;
  padding: 3px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #eef1f5;
}
.fc-modes button {
  min-width: 0;
  min-height: 34px;
  overflow: hidden;
  padding: 6px 8px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #3d4652;
  font-size: 12px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}
.fc-modes button:hover {
  background: rgba(255, 255, 255, 0.72);
}
.fc-modes button.is-active {
  background: var(--brand-primary);
  color: white;
}
.fc-modes button:focus-visible,
.fc-collapsible-trigger:focus-visible {
  outline: 2px solid var(--brand-primary);
  outline-offset: 2px;
}
.fc-primary-action {
  width: 100%;
}
.fc-progress-panel {
  display: grid;
  gap: 7px;
  margin-top: 12px;
  padding: 13px;
  border: 1px solid var(--brand-primary-border);
  border-radius: 10px;
  background: white;
  color: var(--text-muted);
  font-size: 12px;
}
.fc-progress-panel strong {
  color: var(--brand-primary);
  font-size: 13px;
}
.fc-progress {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #e5e8ed;
}
.fc-progress__value {
  height: 100%;
  border-radius: inherit;
  background: var(--brand-primary);
  transition: width 120ms ease-out;
}
.fc-notice {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 12px;
  padding: 11px 12px;
  border: 1px solid var(--brand-primary-border);
  border-radius: 9px;
  background: var(--brand-primary-soft);
  color: #243955;
  font-size: 13px;
  line-height: 1.45;
}
.fc-notice--error {
  border-color: #efc3c3;
  background: #fff7f7;
  color: #8a2525;
}
.fc-error-boundary {
  display: grid;
  gap: 12px;
  margin-top: 20px;
  padding: 18px;
  border: 1px solid #efc3c3;
  border-radius: 12px;
  background: white;
  color: #8a2525;
}
.fc-error-boundary h1 {
  margin: 0;
  color: #752121;
  font-size: 18px;
}
.fc-error-boundary p {
  margin: 5px 0 0;
  color: var(--text-muted);
  font-size: 13px;
  line-height: 1.5;
}
.fc-error-boundary__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.fc-error-boundary details {
  color: var(--text-muted);
  font-size: 12px;
}
.fc-error-boundary summary {
  width: fit-content;
  cursor: pointer;
}
.fc-empty-state,
.fc-no-results {
  display: grid;
  justify-items: center;
  gap: 8px;
  margin-top: 18px;
  padding: 32px 18px;
  border: 1px dashed var(--brand-primary-border);
  border-radius: 12px;
  background: white;
  text-align: center;
}
.fc-empty-state h2,
.fc-no-results h2,
.fc-success h2 {
  margin: 0;
  color: var(--brand-primary);
  font-size: 17px;
}
.fc-empty-state p,
.fc-no-results p,
.fc-success p {
  margin: 0;
  color: var(--text-muted);
  font-size: 13px;
  line-height: 1.5;
}
.fc-spotlight-card {
  --spotlight-x: 50%;
  --spotlight-y: 20%;
  position: relative;
  isolation: isolate;
  overflow: hidden;
}
.fc-spotlight-card::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background: radial-gradient(260px circle at var(--spotlight-x) var(--spotlight-y), rgba(0, 51, 129, 0.085), transparent 68%);
  content: "";
  pointer-events: none;
}
.fc-summary {
  margin-top: 16px;
  padding: 15px;
  border: 1px solid var(--brand-primary-border);
  border-radius: 12px;
  background: white;
  box-shadow: 0 1px 2px rgba(14, 30, 52, 0.04);
}
.fc-summary__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}
.fc-eyebrow {
  margin: 0 0 2px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.fc-summary h2 {
  margin: 0;
  color: var(--brand-primary);
  font-size: 17px;
  line-height: 1.3;
}
.fc-summary__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
  margin-top: 13px;
}
.fc-summary__grid div {
  display: grid;
  gap: 1px;
  min-width: 0;
  padding: 8px;
  border-radius: 8px;
  background: #f5f7fa;
}
.fc-summary__grid span {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fc-summary__grid strong {
  color: var(--brand-primary);
  font-size: 17px;
}
.fc-summary__status,
.fc-summary__correction {
  margin: 10px 0 0;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}
.fc-summary__correction {
  padding-top: 9px;
  border-top: 1px solid var(--border);
  color: #334155;
}
.fc-report-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 9px;
}
.fc-batch-summary {
  margin-top: 13px;
  padding: 15px;
  border: 1px solid #b9ddc9;
  border-radius: 12px;
  background: #f5fcf8;
  color: #315244;
}
.fc-batch-summary--issues {
  border-color: #e7c982;
  background: #fffbef;
  color: #6f571e;
}
.fc-batch-summary--failed {
  border-color: #efc3c3;
  background: #fff7f7;
  color: #8a2525;
}
.fc-batch-summary__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}
.fc-batch-summary h2 {
  margin: 0;
  color: var(--brand-primary);
  font-size: 17px;
}
.fc-batch-summary__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
  margin-top: 12px;
}
.fc-batch-summary__grid div {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 8px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.7);
}
.fc-batch-summary__grid span {
  color: var(--text-muted);
  font-size: 10px;
}
.fc-batch-summary__grid strong {
  color: var(--brand-primary);
  font-size: 16px;
}
.fc-batch-summary > p {
  margin: 10px 0 0;
  font-size: 11px;
  line-height: 1.5;
}
.fc-batch-summary__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 12px;
}
.fc-badge--warning {
  border-color: #e7c982;
  background: #fff4ce;
  color: #725817;
}
.fc-badge--document-source {
  border-color: #b9ddc9;
  background: #f2faf5;
  color: #286142;
}
.fc-document-sources-callout {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 11px;
  padding: 12px;
  border: 1px solid #b9ddc9;
  border-radius: 10px;
  background: #f5fcf8;
  color: #315244;
}
.fc-document-sources-callout p {
  margin: 3px 0 0;
  font-size: 11px;
  line-height: 1.45;
}
.fc-source-review-modal {
  width: min(100%, 560px);
  max-height: min(82vh, 680px);
  overflow-y: auto;
}
.fc-source-review-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}
.fc-source-review-item {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fafbfd;
}
.fc-source-review-item > span {
  display: grid;
  min-width: 0;
  gap: 4px;
}
.fc-source-review-item strong {
  overflow-wrap: anywhere;
  color: var(--brand-primary);
  font-size: 12px;
}
.fc-source-review-item span span {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.4;
}
.fc-source-review-item details {
  color: var(--text-muted);
  font-size: 11px;
}
.fc-source-review-item ul {
  margin: 5px 0 0;
  padding-left: 18px;
}
.fc-success {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-top: 14px;
  padding: 16px;
  border: 1px solid #b9ddc9;
  border-radius: 10px;
  background: #f5fcf8;
  color: #277149;
}
.fc-sticky-actions {
  position: sticky;
  z-index: 20;
  top: 0;
  display: flex;
  width: 100%;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px 12px;
  margin-top: 13px;
  padding: 9px;
  border: 1px solid var(--brand-primary-border);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.97);
  box-shadow: 0 4px 14px rgba(24, 39, 60, 0.08);
  backdrop-filter: blur(8px);
}
.fc-sticky-actions--review {
  justify-content: space-between;
}
.fc-sticky-actions--correction {
  color: #445164;
  font-size: 11px;
}
.fc-sticky-actions--correction strong {
  color: var(--brand-primary);
  font-size: 12px;
}
.fc-sticky-actions__status {
  color: var(--text-muted);
  font-size: 11px;
}
.fc-bulk-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.fc-filters {
  display: grid;
  gap: 11px;
  margin-top: 14px;
  padding: 13px;
  border: 1px solid var(--border);
  border-radius: 11px;
  background: white;
}
.fc-search {
