.fc-badge--class-info {
  border-color: #d5dbe3;
  background: #f4f6f8;
  color: #536172;
}
.fc-finding__status {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  color: var(--text-muted);
