.fc-status--unreviewed {
  border-color: #d8dde4;
  background: #f5f6f8;
  color: #55606e;
}
.fc-status--accepted {
  border-color: var(--brand-primary-border);
  background: var(--brand-primary-soft);
  color: var(--brand-primary);
