  font-size: 11px;
}
.fc-writeback-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 7px;
  border: 1px solid #d5dce6;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 650;
}
.fc-writeback-badge--pending {
  border-color: #ccd9eb;
  background: #f2f6fb;
  color: #344d6e;
}
.fc-writeback-badge--applied {
  border-color: #b9ddc9;
  background: #f2faf5;
  color: #25643f;
}
.fc-writeback-badge--failed {
  border-color: #edcaca;
  background: #fff6f6;
  color: #8a3030;
}
.fc-writeback-badge--stale {
  border-color: #ead4ad;
  background: #fff9ee;
  color: #80551d;
