  display: block;
  margin-bottom: 2px;
  color: #687587;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.fc-source-preview blockquote {
  margin: 0;
  overflow-wrap: anywhere;
  color: #344154;
  font-size: 11px;
  line-height: 1.4;
}
.fc-finding__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 11px;
}
.fc-finding__actions > span {
  display: inline-flex;
}
.fc-review-action {
  min-height: 30px;
  padding: 4px 8px;
  gap: 5px;
  font-size: 11px;
}
.fc-review-action--selected {
  border-color: #26364a;
  background: transparent;
  color: #26364a;
  box-shadow: inset 0 0 0 1px #26364a;
}
.fc-review-action--selected:hover {
  border-color: #172235;
  background: #f5f7fa;
  color: #172235;
}
.fc-filter-checkbox {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 32px;
  color: #46556a;
  font-size: 11px;
}
.fc-filter-checkbox input {
  accent-color: var(--brand-primary);
}
.fc-footnote-accounting {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  padding: 9px 10px;
  border-radius: 7px;
  font-size: 12px;
}
.fc-footnote-accounting--clean {
  color: #245f43;
  background: #eff9f3;
}
.fc-footnote-accounting--partial {
  color: #7a5215;
  background: #fff8e8;
}
.fc-footnote-accounting--partial > span {
  display: grid;
  gap: 4px;
}
.fc-footnote-accounting--partial ul {
  margin: 0;
  padding-left: 17px;
}
.fc-manual-hint {
  flex-basis: 100%;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.45;
}
.fc-details {
  margin-top: 7px;
  border-top: 1px solid #e7eaf0;
}
.fc-details__content {
  min-width: 0;
  padding: 2px 0 5px 23px;
}
.fc-footnote-debug {
  margin: 1px 2px 0;
  padding-top: 2px;
  border-top: 1px solid var(--border);
}
.fc-technical-grid {
  display: grid;
  min-width: 0;
  gap: 7px;
  margin: 0;
}
.fc-technical-grid > div {
  min-width: 0;
}
.fc-technical-grid dt {
  color: #667180;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}
.fc-technical-grid dd {
  min-width: 0;
  margin: 2px 0 0;
  overflow-wrap: anywhere;
  color: #2e3743;
  font-size: 11px;
  line-height: 1.45;
}
.fc-technical-grid pre {
  max-width: 100%;
  margin: 3px 0 0;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
}
.fc-load-more {
  width: 100%;
}
.fc-global-debug {
  margin-top: 13px;
  padding-top: 4px;
  border-top: 1px solid var(--border);
}
.fc-error-details {
  max-width: 100%;
  overflow-x: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: #6e2f2f;
  font-size: 11px;
}
.fc-dialog-backdrop {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(18, 27, 40, 0.44);
}
.fc-dialog {
  width: min(100%, 420px);
  padding: 18px;
  border: 1px solid var(--brand-primary-border);
  border-radius: 12px;
  background: white;
  box-shadow: 0 18px 50px rgba(16, 28, 45, 0.22);
}
.fc-dialog[data-focus-visible] {
  outline: 2px solid var(--brand-primary);
  outline-offset: 2px;
}
.fc-dialog__content {
  outline: none;
}
.fc-dialog h2 {
  margin: 0;
  color: var(--brand-primary);
  font-size: 18px;
}
.fc-dialog p {
  margin: 9px 0 0;
  color: var(--text-muted);
  font-size: 13px;
  line-height: 1.5;
}
.fc-dialog__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 7px;
  margin-top: 16px;
}
.fc-settings-shell {
  padding-top: 18px;
  background: white;
}
