.fc-settings-shell h2 {
  color: var(--brand-primary) !important;
}
.fc-settings-shell input:focus,
.fc-settings-shell select:focus,
.fc-settings-shell textarea:focus {
  border-color: var(--brand-primary) !important;
  outline: none !important;
  box-shadow: 0 0 0 2px var(--brand-primary-soft);
}
.fc-settings-action-card {
  backdrop-filter: blur(8px);
}
.fc-settings-search-field:focus-within {
  border-color: var(--brand-primary) !important;
  box-shadow: 0 0 0 2px var(--brand-primary-soft);
}
.fc-settings-search-field input:focus {
  box-shadow: none !important;
}
.fc-settings-action-card [role="option"]:hover,
