  background: #f7f9fc;
  color: #274b79;
  font: inherit;
  font-size: 13px;
  font-weight: 650;
  text-align: left;
  cursor: pointer;
}
.fc-settings-nested-trigger:focus-visible,
.fc-settings-top-level > button:focus-visible {
