  z-index: 1;
  outline: 2px solid var(--brand-primary);
  outline-offset: -2px;
}
.fc-settings-nested-content {
  min-width: 0;
  padding: 0 8px 8px;
}
.fc-settings-nested-content > section {
  padding: 12px;
}
.fc-settings-directory-actions {
  margin-top: 9px;
}
.fc-settings-source-card,
.fc-settings-alias-card {
  min-width: 0;
  overflow-wrap: anywhere;
}
.fc-settings-source-card input,
.fc-settings-source-card select,
.fc-settings-source-card textarea {
  max-width: 100%;
}
.fc-settings-search-target {
  animation: fc-settings-target-highlight 1.6s ease-out;
  outline: 2px solid var(--brand-primary);
  outline-offset: 2px;
}
@keyframes fc-settings-target-highlight {
  0%, 38% {
    background-color: #e9f2ff;
    box-shadow: 0 0 0 5px rgba(0, 84, 159, 0.12);
  }
  100% {
    background-color: transparent;
    box-shadow: none;
  }
}
@media (max-width: 519px) {
  .fc-summary__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .fc-batch-summary__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .fc-filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .fc-settings-action-card > button,
  .fc-settings-action-card > label:not(.fc-settings-search-field) {
    flex: 1 1 140px;
  }
  .fc-settings-action-card > span {
    flex-basis: 100%;
    margin-left: 0 !important;
  }
}
@media (max-width: 399px) {
  .fc-shell {
    padding-right: 10px;
    padding-left: 10px;
  }
  .fc-brand p {
    display: none;
  }
  .fc-filters-desktop {
    display: none;
  }
  .fc-filters-mobile {
    display: block;
  }
  .fc-filter-grid {
    grid-template-columns: 1fr;
  }
  .fc-filter-status {
    align-items: flex-start;
    flex-direction: column;
  }
  .fc-finding__actions {
    display: grid;
    grid-template-columns: 1fr;
  }
  .fc-finding__actions > button,
  .fc-finding__actions > span,
  .fc-finding__actions > span > button {
    width: 100%;
  }
  .fc-dialog__actions {
    display: grid;
    grid-template-columns: 1fr;
  }
  .fc-document-sources-callout {
    align-items: stretch;
    flex-direction: column;
  }
  .fc-document-sources-callout button {
    width: 100%;
  }
  .fc-settings-action-card > button,
  .fc-settings-action-card > label:not(.fc-settings-search-field) {
    width: 100%;
    flex-basis: 100%;
  }
  .fc-settings-nested-content {
    padding-right: 5px;
    padding-left: 5px;
  }
  .fc-settings-nested-content > section {
    padding: 10px;
  }
  .fc-settings-source-card,
  .fc-settings-alias-card {
    padding: 10px;
  }
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
  .fc-spotlight-card::before {
    display: none;
  }
}
